const attributeMap={'Santiago Cardona home':'Inicio de Santiago Cardona','Main navigation':'Navegación principal','Case study sections':'Secciones del caso de estudio','Close image preview':'Cerrar vista de imagen','Image preview':'Vista de imagen','I’ve worked with':'He trabajado con','Design focus':'Áreas de diseño','Explore my work with Colombia Eléctrica':'Explorar mi trabajo con Colombia Eléctrica','Explore Drones espaciales y asteroides mobile AR case study':'Explorar el caso móvil Drones espaciales y asteroides','View Colombia Eléctrica case study':'Ver el caso de Colombia Eléctrica','Portrait of Santiago Cardona':'Retrato de Santiago Cardona'};
for(const e of document.querySelectorAll('[aria-label],[alt]')){for(const name of ['aria-label','alt'])if(e.hasAttribute(name)){const val=e.getAttribute(name);let es=attributeMap[val]||translations[val];if(!es&&val&&e.matches('img')&&!val.includes('Colombia Eléctrica'))es='Imagen del proyecto: '+(e.closest('.wireframe-figure')||val.toLowerCase().includes('wireframe')?'wireframe documentado': 'interfaz y contexto del proyecto');if(!es&&name==='aria-label'&&val.startsWith('Open '))es='Ampliar imagen del proyecto';if(es)attrs.push([e,name,val,es]);}}
const originalTitle=document.title;let lang='en';const buttons=[...document.querySelectorAll('.language-switch button')];function apply(value){lang=value==='es'?'es':'en';document.documentElement.lang=lang;for(const[n,original,key]of textRecords)n.nodeValue=lang==='es'?original.replace(key,translations[key]):original;for(const[e,name,en,es]of attrs)e.setAttribute(name,lang==='es'?es:en);document.title=lang==='es'?originalTitle.replace('Design Engineer','Ingeniería de diseño').replace('Mobile AR','RA móvil'):originalTitle;for(const btn of buttons){btn.setAttribute('aria-pressed',String(btn.dataset.lang===lang));}document.querySelector('.language-switch').setAttribute('aria-label',lang==='es'?'Idioma':'Language');const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);for(const a of document.querySelectorAll('a[href]')){const u=new URL(a.getAttribute('href'),location.href);if(u.origin===location.origin&&(u.pathname.endsWith('.html')||u.pathname.endsWith('/'))){u.searchParams.set('lang',lang);a.href=u.href;}}}
